select jsonb_build_object('checked_at',clock_timestamp(),'works',(select jsonb_agg(to_jsonb(t)order by id)from public.works t where id=any(array[987155001,987155002,987155003]::int[])),'authors',(select jsonb_agg(to_jsonb(t)order by id)from public.authors t where id=any(array[978300038,987355001,987334001]::int[])),'editions',(select jsonb_agg(to_jsonb(t)order by id)from public.editions t where work_id=any(array[987155001,987155002,987155003]::int[])))as readback;
